import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <vector>
#include <limits>

using namespace cute;

// Generic reduction: input viewed as (outer, reduce, inner) contiguous tensor,
// output viewed as (outer, inner) contiguous tensor. Min-reduce over the
// middle ("reduce") dimension. This covers reduction over any dimension of
// an arbitrary-rank contiguous tensor by collapsing the outer and inner
// dimensions.
template <typename T>
__global__ void min_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int S0, int S1, int S2) // outer, reduce, inner
{
  constexpr int VEC = 4;
  int inner_base = (blockIdx.x * blockDim.x + threadIdx.x) * VEC;
  if (inner_base >= S2) return;
  int remaining = S2 - inner_base;
  for (int outer_idx = blockIdx.y; outer_idx < S0; outer_idx += gridDim.y) {
    const int64_t row_off = (int64_t)outer_idx * (int64_t)S1 * (int64_t)S2 + inner_base;
    if (remaining >= VEC) {
      const T* p0 = X + row_off;
      T minv0, minv1, minv2, minv3;
      bool aligned0 = (((size_t)p0) % 16 == 0);
      if (aligned0) {
        float4 v0 = *reinterpret_cast<const float4*>(p0);
        minv0 = v0.x; minv1 = v0.y; minv2 = v0.z; minv3 = v0.w;
      } else {
        minv0 = p0[0]; minv1 = p0[1]; minv2 = p0[2]; minv3 = p0[3];
      }
      #pragma unroll 4
      for (int h = 1; h < S1; ++h) {
        const T* p = p0 + (int64_t)h * S2;
        bool aligned = (((size_t)p) % 16 == 0);
        if (aligned) {
          float4 v = *reinterpret_cast<const float4*>(p);
          minv0 = v.x < minv0 ? v.x : minv0;
          minv1 = v.y < minv1 ? v.y : minv1;
          minv2 = v.z < minv2 ? v.z : minv2;
          minv3 = v.w < minv3 ? v.w : minv3;
        } else {
          T x0 = p[0], x1 = p[1], x2 = p[2], x3 = p[3];
          minv0 = x0 < minv0 ? x0 : minv0;
          minv1 = x1 < minv1 ? x1 : minv1;
          minv2 = x2 < minv2 ? x2 : minv2;
          minv3 = x3 < minv3 ? x3 : minv3;
        }
      }
      T* ybase = Y + (int64_t)outer_idx * S2 + inner_base;
      bool yaligned = (((size_t)ybase) % 16 == 0);
      if (yaligned) {
        float4 outv;
        outv.x = minv0; outv.y = minv1; outv.z = minv2; outv.w = minv3;
        *reinterpret_cast<float4*>(ybase) = outv;
      } else {
        ybase[0] = minv0; ybase[1] = minv1; ybase[2] = minv2; ybase[3] = minv3;
      }
    } else {
      for (int k = 0; k < remaining; ++k) {
        const T* p = X + row_off + k;
        T minv = p[0];
        for (int h = 1; h < S1; ++h) {
          T v = p[(int64_t)h * S2];
          minv = v < minv ? v : minv;
        }
        Y[(int64_t)outer_idx * S2 + inner_base + k] = minv;
      }
    }
  }
}
torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  auto x_c = x.contiguous();
  int64_t ndim = x_c.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
  int64_t outer = 1;
  for (int64_t i = 0; i < dim; ++i) outer *= x_c.size(i);
  int64_t reduce_size = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t i = dim + 1; i < ndim; ++i) inner *= x_c.size(i);
  std::vector<int64_t> out_shape;
  out_shape.reserve(ndim - 1);
  for (int64_t i = 0; i < ndim; ++i) {
    if (i != dim) out_shape.push_back(x_c.size(i));
  }
  auto y = torch::empty(out_shape, x_c.options());
  TORCH_CHECK(reduce_size > 0, "reduction dimension must have size > 0");
  if (outer == 0 || inner == 0) {
    return y;
  }
  const int threads = 512;
  const int VEC = 4;
  dim3 block(threads);
  int64_t cols_per_block = (int64_t)threads * VEC;
  unsigned grid_x = (unsigned)((inner + cols_per_block - 1) / cols_per_block);
  unsigned grid_y = (unsigned)std::min<int64_t>(outer, 65535);
  dim3 grid(grid_x, grid_y);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  min_reduce_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer, (int)reduce_size, (int)inner);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["min_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension using a
    custom CUTE/CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_forward(x, self.dim)

